import sys, types

# Stub optional imports needed by _pytest.compat in this minimal environment.
attr = types.ModuleType("attr")
def _decorator(cls=None, **kwargs):
    if cls is None:
        return lambda c: c
    return cls
attr.s = attr.attr = _decorator
attr.ib = attr.attrib = lambda *a, **kw: None
sys.modules["attr"] = attr

py = types.ModuleType("py")
py.path = types.SimpleNamespace(local=object)
sys.modules["py"] = py

sys.path.insert(0, "src")
from unittest.mock import patch
from _pytest.compat import getfuncargnames, num_mock_patch_args

class AmbiguousBool:
    def __bool__(self):
        raise ValueError("ambiguous truth value")

class ArrayLike:
    def __eq__(self, other):
        return AmbiguousBool()

array_new = ArrayLike()

@patch("os.path.abspath", new=array_new)
def patched_with_new(x):
    pass

@patch("os.path.abspath")
def patched_without_new(mock_abspath, x):
    pass

assert num_mock_patch_args(patched_with_new) == 0
assert getfuncargnames(patched_with_new) == ("x",)
assert num_mock_patch_args(patched_without_new) == 1
assert getfuncargnames(patched_without_new) == ("x",)
print("reproducer passed")
PY"}

